#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
patch_brat_karta_sloev.py — карта слоёв важности Брата.
Кладёт КАРТА_СЛОЁВ.md на верхний этаж канонического Брата
(GRONDHEIM_CITY/Hexagon/Брат/3_маяки_не_очень/).
Снято по живой репе: 3 архиватора + резиденты + финализаторы
(manifest.json qa_agent) + рабочие слои. Градиент важности.
Запускать из корня репо. Идемпотентен (бэкап .bak если отличается).
  шесть·проверено·до·корня
"""
import os, shutil, base64, datetime

TARGET = 'GRONDHEIM_CITY/Hexagon/Брат/3_маяки_не_очень/КАРТА_СЛОЁВ.md'
B64 = ''

def main():
    content = base64.b64decode(B64).decode("utf-8")
    os.makedirs(os.path.dirname(TARGET), exist_ok=True)
    if os.path.exists(TARGET):
        with open(TARGET, encoding="utf-8") as f:
            cur = f.read()
        if cur == content:
            print(f"  = без изменений: {TARGET}")
            print("шесть·проверено·до·корня"); return
        ts = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        shutil.copy2(TARGET, f"{TARGET}.bak_{ts}")
        print(f"  ~ бэкап + обновлён: {TARGET}")
    else:
        print(f"  + создан: {TARGET}")
    with open(TARGET, "w", encoding="utf-8") as f:
        f.write(content)
    print("Готово.")
    print("шесть·проверено·до·корня")

if __name__ == "__main__":
    main()
